{% extends "base.html" %}
{% load static wagtailcore_tags i18n %}

{% block title %}{% trans 'Search' %}{% endblock %}

{% block content %}
<h1>{% trans 'Search' %}</h1>

<form action="{% url 'search' %}" method="get" toolname="search" tooldescription="Search the Wagtail documentation site. Submits the query and returns the full search results page.">
    <label for="search" class="u-sr-only">Search</label>
    <input type="text" id="search" name="query" toolparamdescription="Search query."{% if search_query %} value="{{ search_query }}"{% endif %}>
    <button class="button">
        {% trans 'Search' %}
    </button>
</form>

{% if search_results %}
<ul>
    {% for result in search_results %}
    <li>
        <h4 dir="auto"><a href="{% pageurl result %}">{{ result }}</a></h4>
        {% if result.search_description %}
        <div dir="auto">{{ result.search_description }}</div>
        {% endif %}
    </li>
    {% endfor %}
</ul>

{% if search_results.has_previous %}
<a href="{% url 'search' %}?query={{ search_query|urlencode }}&amp;page={{ search_results.previous_page_number }}">{% trans 'Previous' %}</a>
{% endif %}

{% if search_results.has_next %}
<a href="{% url 'search' %}?query={{ search_query|urlencode }}&amp;page={{ search_results.next_page_number }}">{% trans 'Next' %}</a>
{% endif %}
{% elif search_query %}
{% trans 'No results found' %}
{% endif %}
{% endblock %}

from django.core.paginator import EmptyPage, PageNotAnInteger, Paginator
from django.template.response import TemplateResponse
from django.utils.translation import gettext as _
from rest_framework import serializers
from rest_framework.decorators import api_view
from rest_framework.response import Response
from wagtail.contrib.search_promotions.models import Query
from wagtail.models import Locale, Page


def search(request):
    search_query = request.GET.get("query", None)
    page = request.GET.get("page", 1)

    # Search
    if search_query:
        search_results = (
            Page.objects.live()
            .public()
            .filter(locale=Locale.get_active())
            .search(search_query)
        )
        query = Query.get(search_query)

        # Record hit
        query.add_hit()
    else:
        search_results = Page.objects.none()

    # Pagination
    paginator = Paginator(search_results, 10)
    try:
        search_results = paginator.page(page)
    except PageNotAnInteger:
        search_results = paginator.page(1)
    except EmptyPage:
        search_results = paginator.page(paginator.num_pages)

    return TemplateResponse(
        request,
        "search/search.html",
        {
            "search_query": search_query,
            "search_results": search_results,
            "SEO_NOINDEX": True,
        },
    )


class PageSerializer(serializers.ModelSerializer):
    parent_section = serializers.SerializerMethodField("get_parent_section")

    class Meta:
        model = Page
        fields = ["id", "title", "search_description", "full_url", "parent_section"]

    def get_parent_section(self, page):
        ancestors = page.get_ancestors()
        if len(ancestors) >= 3:
            return ancestors[2].title
        else:
            return _("Home")


@api_view(["GET"])
def search_json(request):
    if search_query := request.GET.get("query"):
        search_results = (
            Page.objects.live()
            .public()
            .filter(locale=Locale.get_active())
            .autocomplete(search_query)
        )
        query = Query.get(search_query)

        # Record hit
        query.add_hit()
    else:
        search_results = Page.objects.none()
    serializer = PageSerializer(search_results, many=True)
    return Response(serializer.data)

/* global ngettext, interpolate */
import { debounce } from './debounce';
import '../scss/main.scss';
import './theme-detect';
import { initSectionLink } from './section-link';
import { initActiveNavItem } from './active-nav-item';
import { handleFeedback } from './feedback';
import { initWebMcp } from './webmcp';
import MobileMenu from './mobile-menu';
import CopyButton from './copy-button';

initSectionLink();
initActiveNavItem();
handleFeedback();
initWebMcp();

const searchInput = document.querySelector('[data-search-input]');
const searchModal = document.getElementById('search-modal');
const resultsDiv = document.querySelector('[data-results]');
const resultsCountContainer = document.querySelector(
  '[data-results-count-container]',
);

const removeExistingChildren = (parent) => {
  parent.innerHTML = '';
};

const injectResultsInHTML = (results) => {
  removeExistingChildren(resultsDiv);
  removeExistingChildren(resultsCountContainer);

  const resultsCountHeading = document.createElement('h2');
  resultsCountHeading.dir = 'auto';
  const resultHeadingString = ngettext(
    '%s result found.',
    '%s results found.',
    results.length,
  );
  resultsCountHeading.innerText = interpolate(resultHeadingString, [
    results.length,
  ]);
  resultsCountHeading.classList.add('autocomplete__count');
  resultsCountContainer.appendChild(resultsCountHeading);

  results.forEach((result, index) => {
    const resultDiv = document.createElement('a');
    resultDiv.dir = 'auto';
    const resultHeading = document.createElement('h3');
    resultHeading.dir = 'auto';
    const resultDescription = document.createElement('div');
    resultDescription.dir = 'auto';
    const resultParentSection = document.createElement('div');
    resultParentSection.dir = 'auto';
    resultHeading.innerText = result.title;
    resultDescription.innerText = result.search_description;
    resultParentSection.innerText = result.parent_section;
    resultDiv.href = result.full_url;
    resultDiv.appendChild(resultParentSection);
    resultDiv.appendChild(resultHeading);
    resultDiv.appendChild(resultDescription);
    resultParentSection.classList.add('autocomplete__meta');
    resultDescription.classList.add('autocomplete__description');
    resultDiv.classList.add('autocomplete__row');
    resultHeading.classList.add('autocomplete__heading');
    resultsDiv.appendChild(resultDiv);

    requestAnimationFrame(() => {
      setTimeout(() => {
        resultDiv.classList.add('is-visible');
      }, index * 400);
    });
  });
};

const onSearchInputChange = async (event) => {
  const query = event.target.value.trim();

  if (!query) {
    removeExistingChildren(resultsDiv);
    removeExistingChildren(resultsCountContainer);
    return;
  }

  document.querySelector('.search__container').classList.add('is-loading');

  const minDelay = new Promise((resolve) => {
    setTimeout(resolve, 200);
  });

  try {
    const res = await fetch(
      `${window.location.origin}${
        window.languageCode ? `/${window.languageCode}` : ''
      }/search_json/?${new URLSearchParams({
        query,
      }).toString()}`,
    );
    const data = await res.json();
    injectResultsInHTML(data);
  } catch (err) {
    console.log(err);
    window.alert(`Error: ${err}`);
  } finally {
    await minDelay; // wait for 300ms to pass if fetch was faster
    document.querySelector('.search__container').classList.remove('is-loading');
  }
};
const onSearchInputKeyUp = debounce(onSearchInputChange, 150);

searchInput.addEventListener('keyup', (event) => {
  if (event.key === 'Tab') return;
  onSearchInputKeyUp(event);
});

searchModal.addEventListener('shown.bs.modal', () => {
  searchInput.focus();
});

searchModal.addEventListener('hidden.bs.modal', () => {
  searchInput.value = '';
  removeExistingChildren(resultsDiv);
  removeExistingChildren(resultsCountContainer);
});

function initComponent(ComponentClass) {
  const items = document.querySelectorAll(ComponentClass.selector());
  items.forEach((item) => new ComponentClass(item));
}

document.addEventListener('DOMContentLoaded', () => {
  // Remove no-js class if JS is enabled
  document.documentElement.classList.remove('no-js');
  initComponent(MobileMenu);
  initComponent(CopyButton);
});

class MobileMenu {
  static selector() {
    return '[data-mobile-menu-toggle]';
  }

  constructor(node) {
    this.node = node;
    this.body = document.querySelector('body');
    this.mobileMenu = document.querySelector('[data-mobile-menu]');

    this.state = {
      open: false,
    };

    this.bindEventListeners();
  }

  bindEventListeners() {
    this.node.addEventListener('click', () => {
      this.toggle();
    });
  }

  toggle() {
    if (this.state.open) {
      this.close();
    } else {
      this.open();
    }
  }

  open() {
    // Fire a custom event which is useful if we need any other items such as
    // a search box to close when the mobile menu opens
    // Can be listened to with
    // document.addEventListener('onMenuOpen', () => {
    //     // do stuff here...;
    // });
    const menuOpenEvent = new Event('onMenuOpen');
    document.dispatchEvent(menuOpenEvent);
    this.node.classList.add('is-open');
    this.node.setAttribute('aria-expanded', 'true');
    this.body.classList.add('no-scroll');
    this.mobileMenu.classList.add('is-visible');

    this.state.open = true;
  }

  close() {
    this.node.classList.remove('is-open');
    this.node.setAttribute('aria-expanded', 'false');
    this.body.classList.remove('no-scroll');
    this.mobileMenu.classList.remove('is-visible');

    this.state.open = false;
  }
}

export default MobileMenu;

